#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

project_root="$(CDPATH='' cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)"
secret_root="/volume1/docker/billzebub/secrets"
docker_bin="${DOCKER_BIN:-docker}"
if ! command -v "$docker_bin" >/dev/null 2>&1 && [[ -x /usr/local/bin/docker ]]; then
  docker_bin=/usr/local/bin/docker
fi
command -v "$docker_bin" >/dev/null 2>&1 || {
  echo "Docker is unavailable." >&2
  exit 1
}
compose=("$docker_bin" compose --project-name billzebub --file "$project_root/compose.nas.yaml")

write_private_secret_once() {
  local target="$1" value="$2"
  if sudo test -e "$target"; then
    warn "A private file for this setup already exists; refusing to replace it."
    return 1
  fi
  sudo install -m 0600 -o 10001 -g 10001 /dev/null "$target"
  if ! printf '%s\n' "$value" | sudo tee "$target" >/dev/null; then
    sudo rm -f -- "$target"
    return 1
  fi
}

banner "Apple Wallet card setup"

stage "Card metadata"
say "Use a generic slug and display name. Do not use a card number or Wallet label."
ask ACCOUNT_SLUG "Account slug (for example primary-card):"
ask ACCOUNT_DISPLAY_NAME "Display name (for example Primary card):"
ask ACCOUNT_INSTITUTION "Institution (dbs, citi, or uob):"
ask ACCOUNT_CURRENCY "ISO currency (for example SGD):"
[[ "$ACCOUNT_SLUG" =~ ^[a-z0-9]+(-[a-z0-9]+)*$ ]] || {
  warn "The account slug must contain lowercase letters, digits, and single hyphens."
  exit 1
}
[[ -n "$ACCOUNT_DISPLAY_NAME" ]] || {
  warn "A display name is required."
  exit 1
}
case "$ACCOUNT_INSTITUTION" in
  dbs|citi|uob) ;;
  *)
    warn "Choose dbs, citi, or uob."
    exit 1
    ;;
esac
[[ "$ACCOUNT_CURRENCY" =~ ^[A-Z]{3}$ ]] || {
  warn "Use a three-letter uppercase ISO currency."
  exit 1
}
case "$ACCOUNT_INSTITUTION" in
  dbs) STATEMENT_ADAPTER="dbs-credit-card" ;;
  citi) STATEMENT_ADAPTER="citi-credit-card" ;;
  uob) STATEMENT_ADAPTER="uob-credit-card" ;;
esac

stage "Private card inputs"
warn "The next two inputs are hidden. They are written only to root-protected NAS files."
ask_secret STATEMENT_ACCOUNT_IDENTIFIER "Exact statement account identifier:"
ask_secret WALLET_CARD_LABEL "Exact Apple Wallet card label:"
[[ -n "$STATEMENT_ACCOUNT_IDENTIFIER" && -n "$WALLET_CARD_LABEL" ]] || {
  warn "Both private values are required."
  exit 1
}
say "Review these values locally. They are not written until you confirm."
say "Statement account identifier: $STATEMENT_ACCOUNT_IDENTIFIER"
say "Apple Wallet card label: $WALLET_CARD_LABEL"
if ! confirm "Are these exact values correct?"; then
  unset STATEMENT_ACCOUNT_IDENTIFIER WALLET_CARD_LABEL
  warn "Nothing was written. Re-run the wizard when the values are ready."
  exit 1
fi
identifier_host_file="$secret_root/statement-account-identifier-$ACCOUNT_SLUG"
label_host_file="$secret_root/apple-wallet-card-label-$ACCOUNT_SLUG"
identifier_container_file="/run/secrets/$(basename "$identifier_host_file")"
label_container_file="/run/secrets/$(basename "$label_host_file")"

stage "Private files and account validation"
step "Create private mode-0600 files for the statement identifier and Wallet label."
write_private_secret_once "$identifier_host_file" "$STATEMENT_ACCOUNT_IDENTIFIER"
write_private_secret_once "$label_host_file" "$WALLET_CARD_LABEL"
unset STATEMENT_ACCOUNT_IDENTIFIER WALLET_CARD_LABEL
step "Validate the account setup without creating the account."
"${compose[@]}" --profile maintenance run --rm migrate billzebub account bootstrap \
  --slug "$ACCOUNT_SLUG" \
  --display-name "$ACCOUNT_DISPLAY_NAME" \
  --institution "$ACCOUNT_INSTITUTION" \
  --currency "$ACCOUNT_CURRENCY" \
  --statement-adapter "$STATEMENT_ADAPTER" \
  --statement-account-identifier-file "$identifier_container_file" \
  --dry-run
pause "Dry run passed. Press Enter to continue, or Ctrl-C to stop without creating the account."

stage "Financial Account and Wallet alias"
warn "This creates the Financial Account and its private statement-inbox folder."
if confirm "Create this Financial Account now?"; then
  "${compose[@]}" --profile maintenance run --rm migrate billzebub account bootstrap \
    --slug "$ACCOUNT_SLUG" \
    --display-name "$ACCOUNT_DISPLAY_NAME" \
    --institution "$ACCOUNT_INSTITUTION" \
    --currency "$ACCOUNT_CURRENCY" \
    --statement-adapter "$STATEMENT_ADAPTER" \
    --statement-account-identifier-file "$identifier_container_file"
  "${compose[@]}" --profile maintenance run --rm migrate billzebub account apple-wallet-alias \
    --slug "$ACCOUNT_SLUG" --card-label-file "$label_container_file"
else
  warn "Account creation was skipped."
  exit 1
fi

stage "Scoped Shortcut token"
warn "The next command prints a token exactly once. Copy it directly into Shortcuts; do not save it in a file."
if confirm "Issue an Apple Wallet Shortcut token now?"; then
  "${compose[@]}" --profile maintenance run --rm migrate billzebub token issue \
    --name "Apple Wallet Shortcut $ACCOUNT_SLUG" \
    --kind integration --scope shortcut:claims:create
else
  warn "No token was issued. Use the documented token command later."
  exit 1
fi
step "In Shortcuts, set Authorization to Bearer followed by that token."
step "Set its URL to the Tailnet HTTPS base URL shown by tailscale serve status, plus /api/v1/ingestions/apple-wallet."
step "Leave the Shortcut JSON body unchanged."
pause "Press Enter after the Shortcut is updated."

stage "Retained probe backfill"
warn "This copies retained private probe captures into Billzebub; it does not send them anywhere."
if confirm "Import retained probe captures now?"; then
  "${compose[@]}" --profile maintenance run --rm \
    migrate billzebub apple-wallet import-probe --capture-root /import/apple-probe
else
  warn "Probe backfill was skipped. Keep the probe data until it is imported."
fi

stage "Real event and recovery verification"
step "Make one ordinary Apple Pay purchase with this card."
step "Open the Tailnet HTTPS app and verify one provisional Claim or its resulting Review appears."
step "Do not retry a different payload manually; an exact Shortcut retry is the supported idempotency check."
pause "Press Enter after verifying the real event, or Ctrl-C to complete this later."
if confirm "Run the private backup and isolated restore drill now?"; then
  "$project_root/scripts/nas/backup.sh"
  "$project_root/scripts/nas/restore-drill.sh"
else
  warn "Backup and restore drill remain required before retiring the probe."
fi

finish
